"""A concise front door to the complete, multi-page portfolio."""
from showcase import e, media_picture, viewer_link
from leadership import load_leadership


def render_home(profile, media, showcase, sections):
    photos = {item['id']: item for item in media}
    cases = ''.join(f'''<a class="overview-case" href="work.html#{e(item['id'])}"><p class="eyebrow">{e(item['kicker'])}</p><strong class="overview-value">{e(item['visual']['value'])}</strong><p class="overview-label">{e(item['visual']['label'])}</p><h3>{e(item['title'])}</h3><p>{e(item['summary'])}</p><span class="text-link">Explore contribution & evidence →</span></a>''' for item in showcase['cases'])
    feedback = ''.join(f'''<article class="feedback-card"><p class="eyebrow">{e(item['theme'])}</p><p class="feedback-summary">{e(item['summary'])}</p><p class="feedback-role">{e(item['role'])}</p></article>''' for item in load_leadership(profile)['feedback'][:2])
    panel = photos['iea-panel-speaking']
    green = photos['green-talents-ceremony']
    glow = photos['glow']
    return sections['hero'] + sections['strip'] + f'''
<section class="section wrap home-overview" id="work"><div class="section-heading"><div><p class="eyebrow">Enterprise AI</p><h2>Strategy. Products.<br>Business value.</h2></div><a class="text-link" href="work.html">Explore work & leadership →</a></div><div class="overview-cases">{cases}</div></section>
<section class="section wrap home-overview" id="speaking"><div class="home-stage"><a class="home-stage-image" {viewer_link(panel['image'],panel['title'],panel['caption'])}>{media_picture(panel)}<span class="enlarge">View speaking photograph ↗</span></a><div class="home-stage-copy"><p class="eyebrow">International speaker & panellist</p><h2>AI in the room.<br>Ideas in action.</h2><p>From executive roundtables to international research forums, connecting trustworthy AI with the decisions leaders make.</p><p class="stage-venues">IEA Wind · Barclays & Cyber London · Queen Mary University of London · CXO Group</p><p class="latest-note"><strong>Latest panel · November 2026</strong>Agentic AI, connected labs and tactical procurement at Barclays Innovation Hub, London.</p><a class="text-link" href="speaking.html">Talks, interviews & event photographs →</a></div></div></section>
<section class="section wrap home-overview" id="feedback"><div class="section-heading"><div><p class="eyebrow">Stakeholder perspectives</p><h2>Trusted to deliver.</h2></div><a class="text-link" href="work.html#feedback">All six stakeholder perspectives →</a></div><p class="metric-note">Anonymised summaries of individual feedback.</p><div class="home-feedback">{feedback}</div></section>
<section class="section wrap home-overview" aria-label="Explore recognition and research"><div class="destination-grid"><article class="destination-card" id="recognition"><a class="destination-image" href="recognition.html">{media_picture(green)}</a><div><p class="eyebrow">Recognition & contribution</p><h2>International recognition.<br>Lasting contribution.</h2><p>Forbes 30 Under 30 Europe. Green Talents. Outstanding KTP. Invited academic service at ETH Zurich and contributions to the wider AI community.</p><a class="text-link" href="recognition.html">Awards, distinctions & credentials →</a></div></article><article class="destination-card" id="research"><a class="destination-image" href="research.html">{media_picture(glow)}</a><div><p class="eyebrow">Research with reach</p><h2>Ideas that travel<br>beyond publication.</h2><p>Independent references across UCL, Norwegian doctoral guidance, Singapore and beyond. Explore the studies, open papers and Wiley book.</p><a class="text-link" href="research.html">Research impact, publications & PDFs →</a></div></article></div></section>
''' + sections['viewer']
